package org.transittr;
import android.content.*;import android.database.*;import android.database.MatrixCursor;import android.net.Uri;import android.os.ParcelFileDescriptor;import android.provider.OpenableColumns;import java.io.*;
/** Exposes only two generated temporary files through explicitly granted read URIs. */
public final class ShareProvider extends ContentProvider {
 public boolean onCreate(){return true;}private File file(Uri uri)throws FileNotFoundException{if(uri==null||!(getContext().getPackageName()+".share").equals(uri.getAuthority()))throw new FileNotFoundException();String name=uri.getLastPathSegment();if(!"query.png".equals(name)&&!"backup.json".equals(name))throw new FileNotFoundException();File f=new File(new File(getContext().getCacheDir(),"share"),name);if(!f.isFile())throw new FileNotFoundException();return f;}
 public String getType(Uri u){String n=u.getLastPathSegment();return "query.png".equals(n)?"image/png":"backup.json".equals(n)?"application/json":null;}
 public ParcelFileDescriptor openFile(Uri u,String mode)throws FileNotFoundException{if(!"r".equals(mode))throw new FileNotFoundException();return ParcelFileDescriptor.open(file(u),ParcelFileDescriptor.MODE_READ_ONLY);}
 public Cursor query(Uri u,String[] projection,String selection,String[] args,String order){try{File f=file(u);String[] cols=projection==null?new String[]{OpenableColumns.DISPLAY_NAME,OpenableColumns.SIZE}:projection;MatrixCursor c=new MatrixCursor(cols);Object[] row=new Object[cols.length];for(int i=0;i<cols.length;i++){if(OpenableColumns.DISPLAY_NAME.equals(cols[i]))row[i]=f.getName();else if(OpenableColumns.SIZE.equals(cols[i]))row[i]=Long.valueOf(f.length());}c.addRow(row);return c;}catch(FileNotFoundException e){return null;}}
 public Uri insert(Uri u,ContentValues v){throw new UnsupportedOperationException();}public int delete(Uri u,String s,String[] a){throw new UnsupportedOperationException();}public int update(Uri u,ContentValues v,String s,String[] a){throw new UnsupportedOperationException();}
}
